// One output item per XML or PDF attachment, as binary field `data`.
const out = [];
$input.all().forEach((mail, index) => {
  for (const file of Object.values(mail.binary ?? {})) {
    const name = String(file.fileName ?? '');
    const mime = String(file.mimeType ?? '');
    const isXml = /\.xml$/i.test(name) || mime.includes('xml');
    const isPdf = /\.pdf$/i.test(name) || mime === 'application/pdf';
    if (!isXml && !isPdf) continue;
    out.push({
      json: { from: mail.json.from, subject: mail.json.subject, fileName: name, isXml },
      binary: { data: file },
      pairedItem: { item: index },
    });
  }
});
return out;

// One sheet row per attachment. A file that is not an e-invoice (a plain
// PDF, say) gets a row too, with the reason in `status`.
const file = $('One item per attachment').item.json;
const base = { received_from: file.from, subject: file.subject, file: file.fileName };
if ($json.error) {
  return { json: { ...base, status: `not read: ${$json.error}` } };
}
const m = $json.model ?? {};
const totals = m.totals ?? {};
return {
  json: {
    ...base,
    status: 'read',
    invoice_number: m.invoice_number ?? '',
    issue_date: m.issue_date ?? '',
    due_date: m.due_date ?? '',
    seller: m.seller?.name ?? '',
    seller_vat_id: m.seller?.vat_id ?? '',
    currency: m.currency ?? '',
    net_total: totals.tax_exclusive ?? '',
    gross_total: totals.tax_inclusive ?? '',
    amount_due: totals.payable ?? totals.tax_inclusive ?? '',
    payment_iban: m.payment_iban ?? '',
    format: `${$json.detection?.flavor ?? ''} ${$json.detection?.syntax ?? ''}`.trim(),
    source: $json.source ?? '',
  },
};

// The readable view is built from the XML. A ZUGFeRD / Factur-X PDF is
// readable already, so only XML attachments go on.
return $input.all().flatMap((item, index) =>
  item.json.isXml ? [{ json: item.json, binary: item.binary, pairedItem: { item: index } }] : [],
);

// The node returns the readable view as HTML text in `data`; make it a file.
const file = $('Only XML invoices').item.json;
return {
  json: { fileName: file.fileName, from: file.from, subject: file.subject },
  binary: {
    view: {
      data: Buffer.from($json.data, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: `${file.fileName.replace(/\.xml$/i, '')}.html`,
      fileExtension: 'html',
    },
  },
};
